use rustc_span::{RelativeBytePos,MultiByteChar,Pos};
use std::panic::{catch_unwind,AssertUnwindSafe};
mod original{include!(env!("FERRUGO_ANALYZE_SOURCE"));pub fn call(case:&str,lines:&mut Vec<RelativeBytePos>,multi:&mut Vec<MultiByteChar>)->usize{match case{"assert_scan"=>analyze_source_file_generic("λ",3,RelativeBytePos(0),lines,multi),"overflow_line"=>analyze_source_file_generic("\n",1,RelativeBytePos(u32::MAX),lines,multi),"overflow_pos"=>analyze_source_file_generic("aα",3,RelativeBytePos(u32::MAX),lines,multi),"ok"=>analyze_source_file_generic("α\n",3,RelativeBytePos(0),lines,multi),_=>unreachable!()}}}
fn invoke(case:&str){let mut lines=vec![RelativeBytePos(0)];let mut multi=vec![];let result=catch_unwind(AssertUnwindSafe(||original::call(case,&mut lines,&mut multi)));println!("state:{}:{}:{}:{}",result.is_err(),result.unwrap_or(0),lines.iter().map(|p|p.0.to_string()).collect::<Vec<_>>().join(","),multi.iter().map(|p|format!("{}/{}",p.pos.0,p.bytes)).collect::<Vec<_>>().join(","));}
fn escaping(case:&str){let mut lines=vec![RelativeBytePos(0)];let mut multi=vec![];let _=original::call(case,&mut lines,&mut multi);println!("escaped_ok");}
struct Outer{case:String,caught:bool}impl Drop for Outer{fn drop(&mut self){println!("outer_drop:{}",std::thread::panicking());if self.caught{invoke(&self.case)}else{escaping(&self.case)}}}
fn outer_panic(){panic!("outer")}
fn main(){let a:Vec<String>=std::env::args().collect();let(mode,case)=(a[1].clone(),a[2].clone());std::panic::set_hook(Box::new(move|p|{let l=p.location().unwrap();let file=if l.file().ends_with("/panic.rs"){"analyzer-panic.rs"}else{l.file()};let kind=if p.payload().is::<String>(){"owned_string"}else{"static_str"};println!("hook:{kind}:{file}:{}:{}:{}:{}",l.line(),l.column(),p.payload_as_str().unwrap_or("opaque"),std::thread::panicking());if mode=="processing"&&p.payload_as_str()==Some("outer"){invoke(&case);println!("hook_return");}}));let outcome=catch_unwind(AssertUnwindSafe(||match a[1].as_str(){"normal"=>invoke(&a[2]),"processing"=>outer_panic(),"inherited_caught"|"inherited_escape"=>{let _outer=Outer{case:a[2].clone(),caught:a[1]=="inherited_caught"};outer_panic()},_=>unreachable!()}));println!("done:{}:{}",outcome.is_err(),std::thread::panicking());}
